import java.util.Scanner;

class LibraryItem {
    private String title;
    private String itemCode;
    private boolean available;

    LibraryItem(String title, String itemCode) {
        this.title = title;
        this.itemCode = itemCode;
        this.available = true;
    }

    String getSummary() {
        String status = available ? "Tersedia" : "Dipinjam";
        return title + " [" + itemCode + ", " + status + "]";
    }
}

// Buat kelas Thesis (skripsi) turunan LibraryItem dengan dua atribut tambahan: advisor (String) dan year (int). Constructor: Thesis(title, itemCode, advisor, year), panggil super(...) lebih dulu. Override getSummary(): hasil super.getSummary() + " - pembimbing: <advisor>, tahun <year>".

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String title = in.nextLine().trim();
        String code = in.nextLine().trim();
        String advisor = in.nextLine().trim();
        int year = Integer.parseInt(in.nextLine().trim());
        LibraryItem biasa = new LibraryItem("Basis Data", "BK-001");
        LibraryItem skripsi = new Thesis(title, code, advisor, year);
        System.out.println(biasa.getSummary());
        System.out.println(skripsi.getSummary());
    }
}
